import './styles.css'
import { defaultData } from './data'
import { categories, type AppData, type Category, type Currency, type DayPlace, type DayPlan, type Expense, type PackingCategory, type Status, type TripEssential } from './types'
import { icon } from './icons'
import { calculator, registerCalculatorEvents } from './calculator'
import { isAppData, normalizeAppData } from './app-data'
import { selectExpenses, type ExpenseSort } from './expense-list'
import { vietnamesePhraseGroups } from './phrases'

type View = 'overview'|'expenses'|'daily'|'guide'|'calculator'|'settings'
const STORAGE_KEY='da-nang-trip-2026-v2'
const PENDING_SAVE_KEY='da-nang-trip-2026-pending-save'
const views: {id:View; label:string; icon:string}[]=[
  {id:'overview',label:'Overview',icon:'overview'},{id:'expenses',label:'Expenses',icon:'receipt'},{id:'daily',label:'Daily Plan',icon:'calendar'},
  {id:'guide',label:'Trip Guide',icon:'plane'},{id:'calculator',label:'Calculator',icon:'calculator'},{id:'settings',label:'Settings',icon:'settings'}
]
const mobileViews=views.filter(view=>view.id!=='guide')
const colors=['#087c78','#ef8d3b','#5f8fc9','#d6ad42','#8a77b5','#df6f78','#7d918b']
const guideSlides=['หน้าปกและภาพรวมทริป','แผนการเดินทาง 5 วัน','ที่พักและคำแนะนำการเดินทาง','ไฮไลต์วันที่ 1–2','แผนเที่ยววันที่ 3–5','ภาพรวมงบประมาณ']
const clone=<T,>(v:T):T=>JSON.parse(JSON.stringify(v)) as T
type SyncState='loading'|'saving'|'synced'|'offline'
let data:AppData=normalizeAppData(loadData()), view:View='overview', editingId:string|null=null, pendingDelete:string|null=null, editingDayId:string|null=null, editingEssentialId:string|null=null, editingPackingId:string|null=null, editingPinnedNote=false, query='', categoryFilter='all', statusFilter:Status|'all'='all', payerFilter='all', expenseSort:ExpenseSort='date-desc'
let syncState:SyncState='loading', syncTimer:number|undefined, hasPendingSave=loadPendingSave(), localChangeVersion=0
let guideTimer:number|undefined
let cloudPromise:Promise<typeof import('./cloud')>|undefined

function getCloud(){return cloudPromise??=import('./cloud')}
function loadPendingSave(){try{return localStorage.getItem(PENDING_SAVE_KEY)==='true'}catch{return false}}

function loadData():AppData{
  try{const saved=localStorage.getItem(STORAGE_KEY);if(saved)return JSON.parse(saved) as AppData
    const old=localStorage.getItem('trip-budget-v1');if(old){const legacy=JSON.parse(old) as {five?:{items?:{name:string,value:number,note?:string}[]}};const next=clone(defaultData);if(legacy.five?.items){next.expenses=legacy.five.items.map((x,i)=>({id:`legacy-${i}`,date:next.settings.startDate,item:x.name,category:guessCategory(x.name),amount:x.value,currency:'THB',payerId:next.settings.travelers[0].id,status:i<2?'paid':'planned',note:x.note||'นำเข้าจากแผนเดิม'}));return next}}
  }catch{showToast('ไม่สามารถอ่านข้อมูลเดิมได้ จึงใช้ค่าเริ่มต้น','error')}
  return clone(defaultData)
}
function guessCategory(name:string):Category{if(name.includes('เครื่องบิน'))return'Flights';if(name.includes('พัก')||name.includes('Hotel'))return'Accommodation';if(name.includes('รถ')||name.includes('น้ำมัน')||name.includes('สะพาน'))return'Transportation';if(name.includes('กิน')||name.includes('อาหาร'))return'Food';if(name.includes('เที่ยว'))return'Activities';return'Other'}
function saveLocal(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(data))}catch{showToast('บันทึกข้อมูลสำรองในเครื่องไม่สำเร็จ','error')}}
function setPendingSave(pending:boolean){hasPendingSave=pending;try{if(pending)localStorage.setItem(PENDING_SAVE_KEY,'true');else localStorage.removeItem(PENDING_SAVE_KEY)}catch{/* Data remains in the main local backup even if this marker cannot be stored. */}}
function setSyncState(next:SyncState){syncState=next;document.querySelectorAll<HTMLElement>('[data-sync-status]').forEach(el=>{el.className=`sync-status ${next}`;el.textContent=syncText()})}
function syncText(){return syncState==='loading'?'กำลังเชื่อมต่อ':syncState==='saving'?'กำลังบันทึก':syncState==='synced'?'ซิงก์แล้ว':'ออฟไลน์ · เก็บในเครื่อง'}
async function flushSave(){const versionToSave=localChangeVersion;try{const {saveTrip}=await getCloud();await saveTrip(clone(data));if(versionToSave===localChangeVersion){setPendingSave(false);setSyncState('synced')}else{setSyncState('saving');window.clearTimeout(syncTimer);syncTimer=window.setTimeout(()=>void flushSave(),350)}}catch{const wasOffline=syncState==='offline';setSyncState('offline');window.clearTimeout(syncTimer);syncTimer=window.setTimeout(()=>void flushSave(),5000);if(!wasOffline)showToast('ยังส่งข้อมูลขึ้นฐานข้อมูลไม่ได้ เก็บสำรองในเครื่องแล้ว','error')}}
function save(){saveLocal();localChangeVersion+=1;setPendingSave(true);setSyncState('saving');window.clearTimeout(syncTimer);syncTimer=window.setTimeout(()=>void flushSave(),350)}
function toTHB(exp:Expense){return exp.currency==='THB'?exp.amount:exp.amount/data.settings.exchangeRate}
function fmt(value:number,currency:Currency='THB',digits=0){return new Intl.NumberFormat('th-TH',{style:'currency',currency,maximumFractionDigits:digits}).format(value||0)}
function fmtDate(date:string){return new Intl.DateTimeFormat('th-TH',{day:'numeric',month:'short',year:'numeric'}).format(new Date(`${date}T00:00:00`))}
function totals(){const all=data.expenses.reduce((s,e)=>s+toTHB(e),0),paid=data.expenses.filter(e=>e.status==='paid').reduce((s,e)=>s+toTHB(e),0);return{all,paid,planned:all-paid,remaining:data.settings.budgetTHB-all,perPerson:all/data.settings.travelers.length}}
function esc(value:string){return value.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c] as string))}
function mapUrl(name:string,address:string,customUrl:string){const custom=customUrl.trim();if(/^https?:\/\//i.test(custom))return custom;const query=custom||[name,address].filter(Boolean).join(' ');return query?`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}`:''}
function telUrl(phone:string){const normalized=phone.replace(/[^\d+]/g,'');return normalized?`tel:${normalized}`:''}
function showToast(message:string,type:'ok'|'error'='ok'){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className=`toast ${type==='error'?'error':''}`;el.setAttribute('role','status');el.textContent=message;document.body.append(el);setTimeout(()=>el.remove(),2600)}
function backupSection(){return `<section class="card backup-card"><div class="section-head"><div><h2>สำรองและกู้คืนข้อมูล</h2><small>ดาวน์โหลดข้อมูลทั้งหมดก่อนแก้ไขครั้งใหญ่</small></div></div><div class="backup-actions"><button class="btn" type="button" id="exportBackup">ดาวน์โหลด Backup</button><label class="btn" for="importBackup">กู้คืนจากไฟล์</label><input id="importBackup" type="file" accept="application/json,.json" hidden></div><p class="hint">การกู้คืนจะแทนที่ข้อมูลกลางของทุกอุปกรณ์ หลังจากยืนยันแล้ว</p></section>`}
function bindBackup(){document.querySelector('#exportBackup')?.addEventListener('click',()=>{const blob=new Blob([JSON.stringify({schemaVersion:3,exportedAt:new Date().toISOString(),data},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='da-nang-trip-2026-backup.json';link.click();URL.revokeObjectURL(url);showToast('ดาวน์โหลด Backup แล้ว')});document.querySelector<HTMLInputElement>('#importBackup')?.addEventListener('change',async event=>{const file=(event.currentTarget as HTMLInputElement).files?.[0];if(!file)return;try{const parsed=JSON.parse(await file.text()) as {data?:unknown};if(!isAppData(parsed.data))throw new Error('invalid');if(!confirm('กู้คืนไฟล์นี้และแทนที่ข้อมูลกลางของทุกอุปกรณ์หรือไม่?'))return;data=normalizeAppData(clone(parsed.data));save();render();showToast('กู้คืนข้อมูลแล้ว')}catch{showToast('ไฟล์ Backup ไม่ถูกต้อง','error')}})}
function navHtml(items=views){return items.map(v=>`<button data-view="${v.id}" class="${view===v.id?'active':''}" aria-current="${view===v.id?'page':'false'}">${icon(v.icon)}<span>${v.label}</span></button>`).join('')}
function shell(content:string){return `<div class="app"><header class="mobile-head"><div class="brand"><span class="brand-mark">${icon('plane')}</span><span>Da Nang 2026</span></div><span class="sync-status ${syncState}" data-sync-status>${syncText()}</span><button class="menu-btn" id="openMenu" aria-label="เปิดเมนู">${icon('menu')}</button></header><div class="side-overlay"></div><aside class="sidebar"><div class="side-brand"><span class="brand-mark">${icon('plane')}</span><div><strong>Da Nang Trip</strong><small>Budget planner · ${data.settings.travelers.length} คน</small></div></div><nav class="nav" aria-label="เมนูหลัก">${navHtml()}</nav><div class="side-foot"><p class="sync-status ${syncState}" data-sync-status>${syncText()}</p><p class="credit">ภาพสะพานมังกรโดย Supanut Arunoprayote · CC BY 4.0</p><p>มีข้อมูลสำรองในอุปกรณ์นี้</p></div></aside><main class="content">${content}</main><button class="mobile-fab" type="button" data-add aria-label="เพิ่มค่าใช้จ่าย">${icon('plus')}<span>ค่าใช้จ่าย</span></button><nav class="mobile-nav" aria-label="เมนูมือถือ">${navHtml(mobileViews)}</nav></div>`}
function pageHead(title:string,desc:string,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div>${actions?`<div class="actions">${actions}</div>`:''}</div>`}
function renderGuide(){return `${pageHead('คู่มือทริป','ปัดซ้าย–ขวา หรือปล่อยให้ภาพเลื่อนอัตโนมัติ','<button class="btn" data-view="overview">กลับภาพรวม</button>')}<section class="card guide-card" aria-labelledby="guideTitle"><div class="section-head"><div><h2 id="guideTitle">ภาพรวมทริป</h2></div><span class="guide-counter" id="guideCounter">1 / ${guideSlides.length}</span></div><div class="guide-frame"><button class="guide-arrow guide-prev" type="button" aria-label="ภาพก่อนหน้า">‹</button><div class="guide-track" id="tripGuideTrack">${guideSlides.map((label,index)=>`<figure class="guide-slide"><img src="/trip-guide-${index+1}.jpg" alt="${label}" ${index?'loading="lazy"':''}><figcaption><span>${label}</span><a href="/trip-guide-${index+1}.jpg" target="_blank" rel="noopener">เปิดภาพเต็ม</a></figcaption></figure>`).join('')}</div><button class="guide-arrow guide-next" type="button" aria-label="ภาพถัดไป">›</button></div><div class="guide-dots" role="group" aria-label="เลือกหน้าคู่มือ">${guideSlides.map((label,index)=>`<button type="button" data-guide-index="${index}" class="${index===0?'active':''}" aria-label="${label}" aria-current="${index===0?'true':'false'}"></button>`).join('')}</div></section>`}
function bindTripGuide(){window.clearInterval(guideTimer);const track=document.querySelector<HTMLElement>('#tripGuideTrack'),slides=[...document.querySelectorAll<HTMLElement>('.guide-slide')],dots=[...document.querySelectorAll<HTMLButtonElement>('[data-guide-index]')],counter=document.querySelector('#guideCounter');if(!track||!slides.length)return;let active=0;const update=(index:number)=>{active=(index+slides.length)%slides.length;dots.forEach((dot,i)=>{dot.classList.toggle('active',i===active);dot.setAttribute('aria-current',String(i===active))});if(counter)counter.textContent=`${active+1} / ${slides.length}`},go=(index:number)=>{update(index);track.scrollTo({left:slides[active].offsetLeft,behavior:'smooth'})},start=()=>{window.clearInterval(guideTimer);if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches)guideTimer=window.setInterval(()=>go(active+1),6500)},stop=()=>window.clearInterval(guideTimer);document.querySelector('.guide-prev')?.addEventListener('click',()=>{go(active-1);start()});document.querySelector('.guide-next')?.addEventListener('click',()=>{go(active+1);start()});dots.forEach((dot,index)=>dot.addEventListener('click',()=>{go(index);start()}));track.addEventListener('scroll',()=>{const width=track.clientWidth;if(width)update(Math.round(track.scrollLeft/width))},{passive:true});track.addEventListener('pointerdown',stop);track.addEventListener('pointerup',start);track.addEventListener('mouseenter',stop);track.addEventListener('mouseleave',start);track.addEventListener('focusin',stop);track.addEventListener('focusout',start);start()}
function bindGuideShortcut(){document.querySelector('[data-open-guide]')?.addEventListener('click',()=>{view='guide';render();window.scrollTo(0,0)})}

const packingCategories: {id:PackingCategory; label:string}[]=[
  {id:'documents',label:'เอกสาร'},{id:'clothes',label:'เสื้อผ้า'},{id:'medicine',label:'ยา'},{id:'equipment',label:'อุปกรณ์'},{id:'personal',label:'ของใช้ส่วนตัว'}
]
const essentialLabels={flight:'เที่ยวบิน',stay:'ที่พัก',emergency:'ฉุกเฉิน'} as const

function overviewUtilities(){return `<section class="card pinned-note"><div class="pinned-note-main"><span class="utility-icon">${icon('pin')}</span><div><div class="metric-label">โน้ตกลางของครอบครัว</div><p>${data.pinnedNote?esc(data.pinnedNote):'ยังไม่มีโน้ต · เพิ่มจุดนัดพบ เลขห้อง หรือเวลาออกเดินทาง'}</p></div></div><div class="utility-actions"><button class="btn compact" type="button" data-edit-note>${icon('edit')} ${data.pinnedNote?'แก้ไขโน้ต':'เพิ่มโน้ต'}</button><button class="btn compact" type="button" data-open-guide-section="tripEssentials">${icon('info')} ข้อมูลสำคัญ</button><button class="btn compact" type="button" data-open-guide-section="packingChecklist">${icon('checklist')} เช็กลิสต์</button></div></section>`}

function essentialCard(item:TripEssential){const destination=mapUrl(item.title,item.address,item.mapUrl),phone=telUrl(item.phone);return `<article class="essential-item"><div class="essential-top"><span class="category">${essentialLabels[item.kind]}</span><button class="icon-btn" type="button" data-edit-essential="${item.id}" aria-label="แก้ไข ${esc(item.title)}">${icon('edit')}</button></div><h3>${esc(item.title)}</h3>${item.details?`<p>${esc(item.details)}</p>`:'<p class="hint">ยังไม่ได้เพิ่มรายละเอียด</p>'}${item.bookingRef?`<div class="essential-line"><span>เลขการจอง</span><strong>${esc(item.bookingRef)}</strong></div>`:''}${item.address?`<div class="essential-line"><span>ที่อยู่</span><strong>${esc(item.address)}</strong></div>`:''}<div class="utility-actions">${item.bookingRef?`<button class="btn compact" type="button" data-copy="${esc(item.bookingRef)}">${icon('copy')} คัดลอกเลขจอง</button>`:''}${phone?`<a class="btn compact" href="${esc(phone)}">${icon('phone')} โทร</a>`:''}${destination?`<a class="btn compact" href="${esc(destination)}" target="_blank" rel="noopener">${icon('map')} เปิดแผนที่</a>`:''}</div></article>`}

function packingSection(){const packed=data.packingItems.filter(item=>item.packed).length;return `<section class="card utility-section" id="packingChecklist"><div class="section-head"><div><h2>เช็กลิสต์สัมภาระ</h2><small>${packed} / ${data.packingItems.length} รายการพร้อมแล้ว</small></div><button class="btn compact" type="button" data-add-packing>${icon('plus')} เพิ่มรายการ</button></div><div class="packing-groups">${packingCategories.map(category=>{const items=data.packingItems.filter(item=>item.category===category.id);return `<section class="packing-group"><h3>${category.label}</h3>${items.length?items.map(item=>`<div class="packing-row ${item.packed?'packed':''}"><label><input type="checkbox" data-toggle-packing="${item.id}" ${item.packed?'checked':''}><span>${esc(item.name)}</span></label><div class="row-actions"><button class="icon-btn" type="button" data-edit-packing="${item.id}" aria-label="แก้ไข ${esc(item.name)}">${icon('edit')}</button><button class="icon-btn" type="button" data-delete-packing="${item.id}" aria-label="ลบ ${esc(item.name)}">${icon('trash')}</button></div></div>`).join(''):'<p class="hint">ยังไม่มีรายการ</p>'}</section>`}).join('')}</div></section>`}

function phraseSection(){return `<section class="card utility-section" id="vietnamesePhrases"><div class="section-head"><div><h2>ประโยคภาษาเวียดนาม</h2><small>แตะคัดลอกแล้วแสดงให้คนขับหรือพนักงานดูได้ทันที</small></div></div><div class="phrase-groups">${vietnamesePhraseGroups.map(group=>`<section class="phrase-group"><h3>${group.title}</h3>${group.phrases.map(phrase=>`<article class="phrase-row"><div><span>${phrase.thai}</span><strong lang="vi">${phrase.vietnamese}</strong><small>${phrase.pronunciation}</small></div><button class="icon-btn" type="button" data-copy="${esc(phrase.vietnamese)}" aria-label="คัดลอก ${esc(phrase.thai)}">${icon('copy')}</button></article>`).join('')}</section>`).join('')}</div></section>`}

function tripGuideUtilities(){return `<section class="card utility-section" id="tripEssentials"><div class="section-head"><div><h2>ข้อมูลสำคัญของทริป</h2><small>เที่ยวบิน ที่พัก เลขการจอง และเบอร์ติดต่อที่ต้องใช้</small></div></div><div class="essential-grid">${data.tripEssentials.map(essentialCard).join('')}</div><p class="hint privacy-note">เก็บเฉพาะข้อมูลการเดินทางที่จำเป็น ไม่ควรใส่เลขพาสปอร์ตหรือข้อมูลส่วนตัวสำคัญ</p></section>${packingSection()}${phraseSection()}`}

function dailyPlacesHtml(day:DayPlan){if(!day.places.length)return'';return `<div class="day-places"><span class="metric-label">สถานที่</span>${day.places.map(place=>{const destination=mapUrl(place.name,place.address,place.mapUrl);return `<div class="day-place"><div><strong>${esc(place.name||'สถานที่')}</strong>${place.address?`<span>${esc(place.address)}</span>`:''}</div>${destination?`<a class="btn compact" href="${esc(destination)}" target="_blank" rel="noopener">${icon('map')} เปิดแผนที่</a>`:''}</div>`}).join('')}</div>`}

function injectViewUtilities(){if(view==='overview'){const target=document.querySelector('.hero')||document.querySelector('.page-head');target?.insertAdjacentHTML('afterend',overviewUtilities())}if(view==='guide')document.querySelector('.guide-card')?.insertAdjacentHTML('afterend',tripGuideUtilities());if(view==='daily'){const days=[...data.days].sort((a,b)=>a.date.localeCompare(b.date));document.querySelectorAll<HTMLElement>('.day-plan').forEach((card,index)=>{const day=days[index];if(day)card.querySelector('.day-main')?.insertAdjacentHTML('afterend',dailyPlacesHtml(day))})}}

function placeFields(place?:DayPlace){const id=place?.id||crypto.randomUUID();return `<div class="place-editor-row" data-place-id="${id}"><div class="field"><label>ชื่อสถานที่</label><input class="input place-name" value="${esc(place?.name||'')}" placeholder="เช่น Golden Bridge"></div><div class="field"><label>ที่อยู่</label><input class="input place-address" value="${esc(place?.address||'')}" placeholder="เว้นว่างได้"></div><div class="field place-link"><label>ลิงก์แผนที่หรือพิกัด</label><input class="input place-map" value="${esc(place?.mapUrl||'')}" placeholder="เว้นว่างเพื่อค้นจากชื่อและที่อยู่"></div><button class="icon-btn" type="button" data-remove-place aria-label="นำสถานที่นี้ออก">${icon('trash')}</button></div>`}

function injectDayPlacesEditor(){const form=document.querySelector('#dayForm'),actions=form?.querySelector('.modal-actions');if(!form||!actions||form.querySelector('#dayPlaceRows'))return;const day=editingDayId?data.days.find(item=>item.id===editingDayId):null,places=day?.places.length?day.places:[{id:crypto.randomUUID(),name:'',address:'',mapUrl:''}];actions.insertAdjacentHTML('beforebegin',`<fieldset class="place-editor"><legend>สถานที่และแผนที่</legend><p class="hint">ถ้าไม่ใส่ลิงก์ แอปจะค้นหา Google Maps จากชื่อและที่อยู่ให้</p><div id="dayPlaceRows">${places.map(placeFields).join('')}</div><button class="btn compact" type="button" data-add-place>${icon('plus')} เพิ่มสถานที่</button></fieldset>`);form.querySelector('[data-add-place]')?.addEventListener('click',()=>document.querySelector('#dayPlaceRows')?.insertAdjacentHTML('beforeend',placeFields()));form.querySelector('#dayPlaceRows')?.addEventListener('click',event=>{const button=(event.target as HTMLElement).closest('[data-remove-place]');button?.closest('.place-editor-row')?.remove()})}

function noteModal(){return `<div class="modal-backdrop"><form class="modal small-modal" id="noteForm" role="dialog" aria-modal="true" aria-labelledby="noteTitle"><div class="modal-head"><h2 id="noteTitle">โน้ตกลางของครอบครัว</h2><button class="icon-btn" type="button" data-close-utility aria-label="ปิด">${icon('close')}</button></div><div class="field"><label for="pinnedNote">ข้อความสั้น</label><textarea class="textarea" id="pinnedNote" rows="4" maxlength="240" placeholder="เช่น เจอกันที่ล็อบบี้ 07:00 น.">${esc(data.pinnedNote)}</textarea><div class="hint">ไม่ควรใส่ข้อมูลส่วนตัวหรือข้อมูลเอกสารสำคัญ</div></div><div class="modal-actions"><button class="btn" type="button" data-close-utility>ยกเลิก</button><button class="btn primary" type="submit">บันทึกโน้ต</button></div></form></div>`}

function essentialModal(){const item=data.tripEssentials.find(essential=>essential.id===editingEssentialId);if(!item)return'';return `<div class="modal-backdrop"><form class="modal" id="essentialForm" role="dialog" aria-modal="true" aria-labelledby="essentialTitle"><div class="modal-head"><h2 id="essentialTitle">แก้ไขข้อมูล${essentialLabels[item.kind]}</h2><button class="icon-btn" type="button" data-close-utility aria-label="ปิด">${icon('close')}</button></div><div class="form-grid"><div class="field"><label for="essentialName">ชื่อรายการ</label><input class="input" id="essentialName" value="${esc(item.title)}" required autofocus></div><div class="field"><label for="essentialDetails">เที่ยวบิน / เวลาเช็กอิน–เช็กเอาต์ / หมายเหตุ</label><input class="input" id="essentialDetails" value="${esc(item.details)}"></div><div class="field"><label for="essentialBooking">เลขการจอง</label><input class="input" id="essentialBooking" value="${esc(item.bookingRef)}"></div><div class="field"><label for="essentialPhone">เบอร์ติดต่อ</label><input class="input" id="essentialPhone" type="tel" value="${esc(item.phone)}"></div><div class="field"><label for="essentialAddress">ที่อยู่</label><textarea class="textarea" id="essentialAddress" rows="2">${esc(item.address)}</textarea></div><div class="field"><label for="essentialMap">ลิงก์ Google Maps หรือพิกัด</label><input class="input" id="essentialMap" value="${esc(item.mapUrl)}" placeholder="เว้นว่างเพื่อค้นหาจากชื่อและที่อยู่"></div></div><div class="modal-actions"><button class="btn" type="button" data-close-utility>ยกเลิก</button><button class="btn primary" type="submit">บันทึกข้อมูล</button></div></form></div>`}

function packingModal(){const item=editingPackingId?data.packingItems.find(packing=>packing.id===editingPackingId):null;return `<div class="modal-backdrop"><form class="modal small-modal" id="packingForm" role="dialog" aria-modal="true" aria-labelledby="packingTitle"><div class="modal-head"><h2 id="packingTitle">${item?'แก้ไข':'เพิ่ม'}รายการสัมภาระ</h2><button class="icon-btn" type="button" data-close-utility aria-label="ปิด">${icon('close')}</button></div><div class="form-grid"><div class="field"><label for="packingName">รายการ</label><input class="input" id="packingName" value="${esc(item?.name||'')}" required autofocus></div><div class="field"><label for="packingCategory">หมวดหมู่</label><select class="select" id="packingCategory">${packingCategories.map(category=>`<option value="${category.id}" ${item?.category===category.id?'selected':''}>${category.label}</option>`).join('')}</select></div></div><div class="modal-actions"><button class="btn" type="button" data-close-utility>ยกเลิก</button><button class="btn primary" type="submit">บันทึกรายการ</button></div></form></div>`}

function closeUtilityModal(){editingEssentialId=null;editingPackingId=null;editingPinnedNote=false;document.body.dataset.addingPacking='false';render()}

function bindTripUtilities(){document.querySelectorAll<HTMLElement>('[data-open-guide-section]').forEach(button=>button.addEventListener('click',()=>{const section=button.dataset.openGuideSection;view='guide';render();requestAnimationFrame(()=>document.getElementById(section||'')?.scrollIntoView({block:'start'}))}));document.querySelector('[data-edit-note]')?.addEventListener('click',()=>{editingPinnedNote=true;render()});document.querySelectorAll<HTMLElement>('[data-edit-essential]').forEach(button=>button.addEventListener('click',()=>{editingEssentialId=button.dataset.editEssential||null;render()}));document.querySelectorAll<HTMLInputElement>('[data-toggle-packing]').forEach(input=>input.addEventListener('change',()=>{const item=data.packingItems.find(packing=>packing.id===input.dataset.togglePacking);if(item){item.packed=input.checked;save();render()}}));document.querySelector('[data-add-packing]')?.addEventListener('click',()=>{editingPackingId=null;document.body.dataset.addingPacking='true';render()});document.querySelectorAll<HTMLElement>('[data-edit-packing]').forEach(button=>button.addEventListener('click',()=>{editingPackingId=button.dataset.editPacking||null;document.body.dataset.addingPacking='false';render()}));document.querySelectorAll<HTMLElement>('[data-delete-packing]').forEach(button=>button.addEventListener('click',()=>{const item=data.packingItems.find(packing=>packing.id===button.dataset.deletePacking);if(!item||!confirm(`ลบ “${item.name}” ออกจากเช็กลิสต์หรือไม่?`))return;data.packingItems=data.packingItems.filter(packing=>packing.id!==item.id);save();render();showToast('ลบรายการแล้ว')}));document.querySelectorAll<HTMLElement>('[data-copy]').forEach(button=>button.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(button.dataset.copy||'');showToast('คัดลอกแล้ว')}catch{showToast('คัดลอกไม่สำเร็จ','error')}}));document.querySelectorAll('[data-close-utility]').forEach(button=>button.addEventListener('click',closeUtilityModal));document.querySelector<HTMLFormElement>('#noteForm')?.addEventListener('submit',event=>{event.preventDefault();data.pinnedNote=document.querySelector<HTMLTextAreaElement>('#pinnedNote')?.value.trim()||'';editingPinnedNote=false;save();render();showToast('บันทึกโน้ตกลางแล้ว')});document.querySelector<HTMLFormElement>('#essentialForm')?.addEventListener('submit',event=>{event.preventDefault();const item=data.tripEssentials.find(essential=>essential.id===editingEssentialId);if(!item)return;const value=(id:string)=>document.querySelector<HTMLInputElement|HTMLTextAreaElement>(`#${id}`)?.value.trim()||'';item.title=value('essentialName');item.details=value('essentialDetails');item.bookingRef=value('essentialBooking');item.phone=value('essentialPhone');item.address=value('essentialAddress');item.mapUrl=value('essentialMap');editingEssentialId=null;save();render();showToast('บันทึกข้อมูลสำคัญแล้ว')});document.querySelector<HTMLFormElement>('#packingForm')?.addEventListener('submit',event=>{event.preventDefault();const name=document.querySelector<HTMLInputElement>('#packingName')?.value.trim()||'',category=document.querySelector<HTMLSelectElement>('#packingCategory')?.value as PackingCategory;if(!name)return;const item=editingPackingId?data.packingItems.find(packing=>packing.id===editingPackingId):null;if(item){item.name=name;item.category=category}else data.packingItems.push({id:crypto.randomUUID(),name,category,packed:false});editingPackingId=null;document.body.dataset.addingPacking='false';save();render();showToast('บันทึกเช็กลิสต์แล้ว')})}
function overview(){const t=totals(),catTotals=categories.map(c=>({name:c,value:data.expenses.filter(e=>e.category===c).reduce((s,e)=>s+toTHB(e),0)})).filter(x=>x.value>0);const degs=catTotals.reduce<{name:string,value:number,color:string,start:number,end:number}[]>((a,x,i)=>{const start=a.at(-1)?.end||0;const end=start+(x.value/t.all*360);a.push({...x,color:colors[i],start,end});return a},[]);const gradient=degs.map(x=>`${x.color} ${x.start}deg ${x.end}deg`).join(',');const spentPct=Math.min(100,t.all/data.settings.budgetTHB*100);return `${pageHead('ภาพรวมทริป','งบประมาณและค่าใช้จ่ายของผู้เดินทาง 4 คน','<button class="btn" data-open-guide>'+icon('plane')+' คู่มือทริป</button><button class="btn primary" data-add>'+icon('plus')+' เพิ่มค่าใช้จ่าย</button>')}<section class="hero"><img src="/da-nang-dragon-bridge.jpg" alt="สะพานมังกรเหนือแม่น้ำฮันในดานังยามค่ำคืน"><div class="hero-content"><span class="tag">VIETNAM · 2026</span><h2>${esc(data.settings.tripName)}</h2><p>วางแผนให้ครบ จ่ายอย่างสบายใจ แล้วออกไปสนุกกับดานัง</p><div class="hero-meta"><span>${icon('calendar',18)} ${fmtDate(data.settings.startDate)} — ${fmtDate(data.settings.endDate)}</span><span>${icon('users',18)} ${data.settings.travelers.length} คน</span></div></div></section><section class="grid summary-grid"><div class="card"><div class="metric-label">งบประมาณรวม</div><div class="metric-value">${fmt(data.settings.budgetTHB)}</div><div class="metric-sub">กำหนดได้ใน Settings</div></div><div class="card"><div class="metric-label">จ่ายแล้ว</div><div class="metric-value">${fmt(t.paid)}</div><div class="metric-sub">รายการสถานะ Paid</div></div><div class="card"><div class="metric-label">คาดการณ์</div><div class="metric-value">${fmt(t.planned)}</div><div class="metric-sub">รายการที่วางแผนไว้</div></div><div class="card accent"><div class="metric-label">งบคงเหลือ</div><div class="metric-value">${fmt(t.remaining)}</div><div class="metric-sub">หลังรวมรายการทั้งหมด</div></div><div class="card"><div class="metric-label">เฉลี่ยต่อคน</div><div class="metric-value">${fmt(t.perPerson)}</div><div class="metric-sub">หาร ${data.settings.travelers.length} คน</div></div></section><section class="grid section-grid"><article class="card"><div class="section-head"><div><h2>ค่าใช้จ่ายตามหมวดหมู่</h2><small>รวม THB และ VND หลังแปลงค่า</small></div></div><div class="chart-wrap"><div class="donut" role="img" aria-label="กราฟค่าใช้จ่ายตามหมวดหมู่" style="background:conic-gradient(${gradient})"></div><div class="legend">${degs.map(x=>`<div class="legend-row"><span class="dot" style="background:${x.color}"></span><span>${x.name}</span><strong>${fmt(x.value)}</strong></div>`).join('')}</div></div></article><article class="card"><div class="section-head"><div><h2>งบประมาณเทียบค่าใช้จ่าย</h2><small>รวมรายการจ่ายแล้วและคาดการณ์</small></div></div><div class="budget-bars"><div><div class="bar-label"><span>งบประมาณ</span><strong>${fmt(data.settings.budgetTHB)}</strong></div><div class="bar"><span style="width:100%"></span></div></div><div><div class="bar-label"><span>ค่าใช้จ่ายทั้งหมด</span><strong>${fmt(t.all)}</strong></div><div class="bar orange"><span style="width:${spentPct}%"></span></div></div><div class="notice">อัตราที่ใช้: 1 THB = ${data.settings.exchangeRate.toLocaleString('th-TH')} VND · แก้ไขได้ใน Settings</div></div></article></section>`}
function filteredExpenses(){return selectExpenses(data.expenses,{query,category:categoryFilter,status:statusFilter,payerId:payerFilter,sort:expenseSort},toTHB,id=>data.settings.travelers.find(person=>person.id===id)?.name||'')}
function expenseResults(){const rows=filteredExpenses(),total=rows.reduce((sum,expense)=>sum+toTHB(expense),0),actions=(e:Expense)=>`<div class="row-actions"><button class="icon-btn expense-action" data-edit="${e.id}" aria-label="แก้ไข ${esc(e.item)}">${icon('edit')}<span>แก้ไข</span></button><button class="icon-btn expense-action danger-action" data-delete="${e.id}" aria-label="ลบ ${esc(e.item)}">${icon('trash')}<span>ลบ</span></button></div>`;return `<div class="expense-result-meta" aria-live="polite"><strong>${rows.length} รายการ</strong><span>รวม ${fmt(total)}</span></div>${rows.length?`<div class="table-scroll expense-table"><table><thead><tr><th>วันที่</th><th>รายการ</th><th>หมวดหมู่</th><th>จำนวนเงิน</th><th>ผู้จ่าย</th><th>สถานะ</th><th>จัดการ</th></tr></thead><tbody>${rows.map(e=>`<tr><td>${fmtDate(e.date)}</td><td><strong>${esc(e.item)}</strong><div class="metric-sub">${esc(e.note||'—')}</div></td><td><span class="category">${e.category}</span></td><td><strong>${fmt(e.amount,e.currency,e.currency==='VND'?0:2)}</strong>${e.currency==='VND'?`<div class="metric-sub">≈ ${fmt(toTHB(e))}</div>`:''}</td><td>${esc(data.settings.travelers.find(p=>p.id===e.payerId)?.name||'—')}</td><td><span class="status ${e.status}">${e.status==='paid'?'จ่ายแล้ว':'คาดการณ์'}</span></td><td>${actions(e)}</td></tr>`).join('')}</tbody></table></div><div class="expense-mobile-list">${rows.map(e=>`<article class="expense-mobile-card"><div class="expense-mobile-head"><div><strong>${esc(e.item)}</strong><span>${fmtDate(e.date)}</span></div><div class="expense-mobile-amount"><strong>${fmt(e.amount,e.currency,e.currency==='VND'?0:2)}</strong>${e.currency==='VND'?`<span>≈ ${fmt(toTHB(e))}</span>`:''}</div></div><div class="expense-mobile-tags"><span class="category">${e.category}</span><span class="status ${e.status}">${e.status==='paid'?'จ่ายแล้ว':'คาดการณ์'}</span></div><details class="expense-mobile-details"><summary>ดูรายละเอียด</summary><div class="expense-mobile-detail-body"><dl><div><dt>ผู้จ่าย</dt><dd>${esc(data.settings.travelers.find(p=>p.id===e.payerId)?.name||'—')}</dd></div><div><dt>หมายเหตุ</dt><dd>${esc(e.note||'ไม่มีหมายเหตุ')}</dd></div></dl>${actions(e)}</div></details></article>`).join('')}</div>`:`<div class="empty">${icon('receipt',34)}<strong>ไม่พบรายการค่าใช้จ่าย</strong><span>ลองเปลี่ยนตัวกรองหรือคำค้นหา</span></div>`}`}
function expenseTable(){return `${pageHead('รายการค่าใช้จ่าย','เพิ่ม แก้ไข ค้นหา และติดตามสถานะการชำระ','<button class="btn primary" data-add>'+icon('plus')+' เพิ่มรายการ</button>')}<section class="card table-card"><div class="toolbar expense-toolbar"><label class="search">${icon('search')}<input class="input" id="expenseSearch" value="${esc(query)}" placeholder="ค้นหารายการ หมายเหตุ หรือผู้จ่าย" aria-label="ค้นหารายการ"></label><details class="expense-filter-details"><summary>ตัวกรองและการเรียง</summary><div class="expense-filter-panel"><select class="select" id="expenseCategory" aria-label="กรองหมวดหมู่"><option value="all">ทุกหมวดหมู่</option>${categories.map(c=>`<option ${categoryFilter===c?'selected':''}>${c}</option>`).join('')}</select><select class="select" id="expenseStatus" aria-label="กรองสถานะ"><option value="all">ทุกสถานะ</option><option value="paid" ${statusFilter==='paid'?'selected':''}>จ่ายแล้ว</option><option value="planned" ${statusFilter==='planned'?'selected':''}>คาดการณ์</option></select><select class="select" id="expensePayer" aria-label="กรองผู้จ่าย"><option value="all">ผู้จ่ายทุกคน</option>${data.settings.travelers.map(person=>`<option value="${person.id}" ${payerFilter===person.id?'selected':''}>${esc(person.name)}</option>`).join('')}</select><select class="select" id="expenseSort" aria-label="เรียงรายการ"><option value="date-desc" ${expenseSort==='date-desc'?'selected':''}>วันที่: ใหม่ไปเก่า</option><option value="date-asc" ${expenseSort==='date-asc'?'selected':''}>วันที่: เก่าไปใหม่</option><option value="amount-desc" ${expenseSort==='amount-desc'?'selected':''}>ยอด: มากไปน้อย</option><option value="amount-asc" ${expenseSort==='amount-asc'?'selected':''}>ยอด: น้อยไปมาก</option><option value="category" ${expenseSort==='category'?'selected':''}>หมวดหมู่</option><option value="status" ${expenseSort==='status'?'selected':''}>สถานะ</option></select><button class="btn" id="clearExpenseFilters" type="button">ล้างตัวกรอง</button></div></details></div><div id="expenseResults">${expenseResults()}</div></section>`}
function updateExpenseResults(){const root=document.querySelector('#expenseResults');if(!root)return;root.innerHTML=expenseResults();bindExpenseRows()}
function bindExpenseRows(){document.querySelectorAll<HTMLElement>('[data-edit]').forEach(b=>b.onclick=()=>{editingId=b.dataset.edit||null;document.body.dataset.adding='false';render()});document.querySelectorAll<HTMLElement>('[data-delete]').forEach(b=>b.onclick=()=>{pendingDelete=b.dataset.delete||null;render()})}
function bindExpenseFilters(){const search=document.querySelector<HTMLInputElement>('#expenseSearch');if(search)search.oninput=()=>{query=search.value;updateExpenseResults()};const bindSelect=(id:string,update:(value:string)=>void)=>{const select=document.querySelector<HTMLSelectElement>(`#${id}`);if(select)select.onchange=()=>{update(select.value);updateExpenseResults()}};bindSelect('expenseCategory',value=>categoryFilter=value);bindSelect('expenseStatus',value=>statusFilter=value as Status|'all');bindSelect('expensePayer',value=>payerFilter=value);bindSelect('expenseSort',value=>expenseSort=value as ExpenseSort);document.querySelector('#clearExpenseFilters')?.addEventListener('click',()=>{query='';categoryFilter='all';statusFilter='all';payerFilter='all';expenseSort='date-desc';render()})}
function daily(){const days=[...data.days].sort((a,b)=>a.date.localeCompare(b.date)),knownIds=new Set(days.map(day=>day.id)),outside=data.expenses.filter(expense=>!expense.dayId||!knownIds.has(expense.dayId));return `${pageHead('แผนรายวัน','วางกิจกรรมและติดตามค่าใช้จ่ายจริงของแต่ละวัน','<button class="btn primary" data-add-day>'+icon('plus')+' เพิ่มวัน</button>')}<section class="timeline">${days.length?days.map((day,index)=>{const expenses=data.expenses.filter(expense=>expense.dayId===day.id),actual=expenses.reduce((sum,expense)=>sum+toTHB(expense),0),balance=day.budgetTHB-actual;return `<article class="card day-plan"><div class="day-main"><div class="datebox"><small>DAY ${index+1}</small><span>${new Date(`${day.date}T00:00:00`).getDate()}</span></div><div><h3>${esc(day.title)}</h3><p>${esc(day.activities||'ยังไม่มีกิจกรรม')}</p><small>${fmtDate(day.date)}</small></div><div class="row-actions"><button class="icon-btn" data-edit-day="${day.id}" aria-label="แก้ไข ${esc(day.title)}">${icon('edit')}</button><button class="icon-btn" data-delete-day="${day.id}" aria-label="ลบ ${esc(day.title)}">${icon('trash')}</button></div></div><div class="day-budget"><span>งบ ${fmt(day.budgetTHB)}</span><span>ใช้จริง ${fmt(actual)}</span><strong class="${balance<0?'over-budget':''}">${balance<0?'เกินงบ':'เหลือ'} ${fmt(Math.abs(balance))}</strong></div><details class="day-details"><summary>${expenses.length} รายการ · ดูรายละเอียด</summary><div class="day-expenses">${expenses.length?expenses.map(expense=>`<button data-edit="${expense.id}" class="day-expense"><span>${esc(expense.item)}</span><strong>${fmt(toTHB(expense))}</strong></button>`).join(''):'<span class="hint">ยังไม่มีค่าใช้จ่ายของวันนี้</span>'}<button class="btn day-add-expense" data-add-day-expense="${day.id}">${icon('plus')} เพิ่มค่าใช้จ่ายวันนี้</button></div></details></article>`}).join(''):`<div class="card empty">${icon('calendar',34)}<strong>ยังไม่มีแผนรายวัน</strong><span>เพิ่มวันแรกเพื่อเริ่มวางกิจกรรมและงบประมาณ</span></div>`}</section>${outside.length?`<section class="card outside-plan"><div class="section-head"><div><h2>ค่าใช้จ่ายนอกแผน</h2><small>${outside.length} รายการ · ${fmt(outside.reduce((sum,expense)=>sum+toTHB(expense),0))}</small></div></div>${outside.map(expense=>`<button data-edit="${expense.id}" class="day-expense"><span>${esc(expense.item)}</span><strong>${fmt(toTHB(expense))}</strong></button>`).join('')}</section>`:''}`}
function settings(){return `${pageHead('ตั้งค่าทริป','แก้ไขข้อมูลงบประมาณ ผู้เดินทาง และอัตราแลกเปลี่ยน')}<section class="grid settings-grid"><form class="card" id="settingsForm"><div class="section-head"><h2>ข้อมูลทริป</h2></div><div class="form-grid"><div class="field"><label for="tripName">ชื่อทริป</label><input class="input" id="tripName" value="${esc(data.settings.tripName)}" required></div><div class="field"><label for="budget">งบประมาณรวม (THB)</label><input class="input" id="budget" type="number" min="0" value="${data.settings.budgetTHB}" required></div><div class="field"><label for="startDate">วันเริ่มต้น</label><input class="input" id="startDate" type="date" value="${data.settings.startDate}" required></div><div class="field"><label for="endDate">วันสิ้นสุด</label><input class="input" id="endDate" type="date" value="${data.settings.endDate}" required></div><div class="field"><label for="exchangeRate">อัตราแลกเปลี่ยน</label><input class="input" id="exchangeRate" type="number" min="1" step="0.01" value="${data.settings.exchangeRate}" required><div class="hint">1 THB = กี่ VND</div></div></div><div class="modal-actions"><button class="btn" type="button" id="resetData">คืนค่าเริ่มต้น</button><button class="btn primary" type="submit">${icon('check')} บันทึกการตั้งค่า</button></div></form><article class="card"><div class="section-head"><h2>ผู้เดินทาง ${data.settings.travelers.length} คน</h2></div>${data.settings.travelers.map((p,i)=>`<label class="traveler-row"><span class="traveler-num">${i+1}</span><input class="input traveler-name" data-person="${p.id}" value="${esc(p.name)}" aria-label="ชื่อผู้เดินทาง ${i+1}"></label>`).join('')}<p class="hint">ชื่อผู้เดินทางจะใช้ในช่องผู้จ่ายและหน้าสรุปการหารเงิน</p></article></section>`}
function dayModal(){const day=editingDayId?data.days.find(item=>item.id===editingDayId):null;return `<div class="modal-backdrop"><form class="modal" id="dayForm" role="dialog" aria-modal="true" aria-labelledby="dayModalTitle"><div class="modal-head"><h2 id="dayModalTitle">${day?'แก้ไข':'เพิ่ม'}แผนรายวัน</h2><button class="icon-btn" type="button" data-close-day aria-label="ปิด">${icon('close')}</button></div><div class="form-grid"><div class="field"><label for="dayDate">วันที่</label><input class="input" id="dayDate" type="date" value="${day?.date||data.settings.startDate}" required></div><div class="field"><label for="dayTitle">ชื่อแผน</label><input class="input" id="dayTitle" value="${esc(day?.title||'')}" required autofocus></div><div class="field"><label for="dayBudget">งบประมาณ (THB)</label><input class="input" id="dayBudget" type="number" min="0" step="0.01" value="${day?.budgetTHB??''}" required></div><div class="field"><label for="dayActivities">กิจกรรม</label><textarea class="textarea" id="dayActivities" rows="3" placeholder="เช่น คาเฟ่ · Hoi An · ตลาดกลางคืน">${esc(day?.activities||'')}</textarea></div></div><div class="modal-actions"><button class="btn" type="button" data-close-day>ยกเลิก</button><button class="btn primary" type="submit">บันทึกแผน</button></div></form></div>`}
function injectExpenseDaySelector(){const date=document.querySelector<HTMLInputElement>('#expDate'),form=document.querySelector('#expenseForm');if(!date||!form||form.querySelector('#expDay'))return;const exp=editingId?data.expenses.find(item=>item.id===editingId):null,selected=exp?.dayId||document.body.dataset.expenseDay||'',field=`<div class="field"><label for="expDay">แผนรายวัน</label><select class="select" id="expDay"><option value="">นอกแผนรายวัน</option>${[...data.days].sort((a,b)=>a.date.localeCompare(b.date)).map(day=>`<option value="${day.id}" ${selected===day.id?'selected':''}>${fmtDate(day.date)} · ${esc(day.title)}</option>`).join('')}</select></div>`;date.closest('.field')?.insertAdjacentHTML('afterend',field);document.querySelector<HTMLSelectElement>('#expDay')?.addEventListener('change',event=>{const day=data.days.find(item=>item.id===(event.currentTarget as HTMLSelectElement).value);if(day)date.value=day.date})}
function closeDayModal(){editingDayId=null;document.body.dataset.addingDay='false';render()}
function submitDay(event:Event){event.preventDefault();const date=document.querySelector<HTMLInputElement>('#dayDate')?.value||'',title=document.querySelector<HTMLInputElement>('#dayTitle')?.value.trim()||'',activities=document.querySelector<HTMLTextAreaElement>('#dayActivities')?.value.trim()||'',budgetTHB=Number(document.querySelector<HTMLInputElement>('#dayBudget')?.value),places=[...document.querySelectorAll<HTMLElement>('.place-editor-row')].map(row=>({id:row.dataset.placeId||crypto.randomUUID(),name:row.querySelector<HTMLInputElement>('.place-name')?.value.trim()||'',address:row.querySelector<HTMLInputElement>('.place-address')?.value.trim()||'',mapUrl:row.querySelector<HTMLInputElement>('.place-map')?.value.trim()||''})).filter(place=>place.name||place.address||place.mapUrl);if(!date||!title||!Number.isFinite(budgetTHB)||budgetTHB<0){showToast('กรุณาตรวจสอบข้อมูลแผนรายวัน','error');return}if(places.some(place=>!place.name)){showToast('กรุณาใส่ชื่อสถานที่ หรือเอาแถวที่ไม่ใช้แล้วออก','error');return}if(data.days.some(day=>day.date===date&&day.id!==editingDayId)){showToast('วันที่นี้มีแผนอยู่แล้ว','error');return}const next:DayPlan={id:editingDayId||crypto.randomUUID(),date,title,activities,budgetTHB,places};if(editingDayId){data.days=data.days.map(day=>day.id===editingDayId?next:day);data.expenses=data.expenses.map(expense=>expense.dayId===editingDayId?{...expense,date}:expense)}else data.days.push(next);editingDayId=null;document.body.dataset.addingDay='false';save();render();showToast('บันทึกแผนรายวันแล้ว')}
function bindDaily(){document.querySelector('[data-add-day]')?.addEventListener('click',()=>{editingDayId=null;document.body.dataset.addingDay='true';render()});document.querySelectorAll<HTMLElement>('[data-edit-day]').forEach(button=>button.addEventListener('click',()=>{editingDayId=button.dataset.editDay||null;document.body.dataset.addingDay='false';render()}));document.querySelectorAll<HTMLElement>('[data-delete-day]').forEach(button=>button.addEventListener('click',()=>{const id=button.dataset.deleteDay,day=data.days.find(item=>item.id===id);if(!id||!day||!confirm(`ลบแผน “${day.title}” หรือไม่? ค่าใช้จ่ายจะย้ายไปอยู่นอกแผน`))return;data.days=data.days.filter(item=>item.id!==id);data.expenses=data.expenses.map(expense=>expense.dayId===id?{...expense,dayId:null}:expense);save();render();showToast('ลบแผนและเก็บค่าใช้จ่ายไว้นอกแผนแล้ว')}));document.querySelectorAll<HTMLElement>('[data-add-day-expense]').forEach(button=>button.addEventListener('click',()=>{editingId=null;document.body.dataset.expenseDay=button.dataset.addDayExpense||'';document.body.dataset.adding='true';render()}));document.querySelectorAll('[data-close-day]').forEach(button=>button.addEventListener('click',closeDayModal));document.querySelector<HTMLFormElement>('#dayForm')?.addEventListener('submit',submitDay)}
function expenseModal(){const exp=editingId?data.expenses.find(e=>e.id===editingId):null,recent=data.expenses[0],currency=exp?.currency||recent?.currency||'THB',payerId=exp?.payerId||recent?.payerId||data.settings.travelers[0].id;return `<div class="modal-backdrop" role="presentation"><form class="modal expense-sheet" id="expenseForm" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="modal-head"><h2 id="modalTitle">${exp?'แก้ไข':'เพิ่ม'}ค่าใช้จ่าย</h2><button class="icon-btn" type="button" data-close aria-label="ปิด">${icon('close')}</button></div><div class="form-grid expense-primary-fields"><div class="field"><label for="expItem">รายการ</label><input class="input" id="expItem" value="${esc(exp?.item||'')}" required autofocus></div><div class="field"><label for="expAmount">จำนวนเงิน</label><input class="input" id="expAmount" type="number" inputmode="decimal" min="0" step="0.01" value="${exp?.amount||''}" required></div><div class="field"><label for="expCurrency">สกุลเงิน</label><select class="select" id="expCurrency"><option ${currency==='THB'?'selected':''}>THB</option><option ${currency==='VND'?'selected':''}>VND</option></select></div><div class="field"><label for="expCategory">หมวดหมู่</label><select class="select" id="expCategory">${categories.map(c=>`<option ${exp?.category===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label for="expStatus">สถานะ</label><select class="select" id="expStatus"><option value="planned" ${exp?.status==='planned'?'selected':''}>คาดการณ์</option><option value="paid" ${exp?.status==='paid'?'selected':''}>จ่ายแล้ว</option></select></div></div><details class="expense-form-more" ${exp?'open':''}><summary>รายละเอียดเพิ่มเติม</summary><div class="form-grid"><div class="field"><label for="expDate">วันที่</label><input class="input" id="expDate" type="date" value="${exp?.date||data.settings.startDate}" required></div><div class="field"><label for="expPayer">ผู้จ่าย</label><select class="select" id="expPayer">${data.settings.travelers.map(p=>`<option value="${p.id}" ${payerId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label for="expNote">หมายเหตุ</label><textarea class="textarea" id="expNote" rows="2">${esc(exp?.note||'')}</textarea></div></div></details><div class="modal-actions"><button class="btn" type="button" data-close>ยกเลิก</button><button class="btn primary" type="submit">บันทึกรายการ</button></div></form></div>`}
function deleteModal(){const exp=data.expenses.find(e=>e.id===pendingDelete);return `<div class="modal-backdrop"><div class="modal" role="alertdialog" aria-modal="true" aria-labelledby="deleteTitle"><div class="modal-head"><h2 id="deleteTitle">ลบรายการนี้หรือไม่?</h2></div><p>“${esc(exp?.item||'รายการนี้')}” จะถูกลบออกจากสรุปค่าใช้จ่าย คุณไม่สามารถย้อนกลับได้</p><div class="modal-actions"><button class="btn" data-close>ยกเลิก</button><button class="btn danger" id="confirmDelete">${icon('trash')} ลบรายการ</button></div></div></div>`}
function render(){const app=document.querySelector<HTMLDivElement>('#app');if(!app)return;const pages={overview,expenses:expenseTable,daily,guide:renderGuide,calculator:()=>calculator({exchangeRate:data.settings.exchangeRate,travelers:data.settings.travelers.length}),settings:()=>settings()+backupSection()};app.innerHTML=shell(pages[view]());injectViewUtilities();if(editingId!==null||document.body.dataset.adding==='true')app.insertAdjacentHTML('beforeend',expenseModal());if(view==='daily'&&(editingDayId!==null||document.body.dataset.addingDay==='true')){app.insertAdjacentHTML('beforeend',dayModal());injectDayPlacesEditor()}if(editingPinnedNote)app.insertAdjacentHTML('beforeend',noteModal());if(editingEssentialId)app.insertAdjacentHTML('beforeend',essentialModal());if(editingPackingId!==null||document.body.dataset.addingPacking==='true')app.insertAdjacentHTML('beforeend',packingModal());if(pendingDelete)app.insertAdjacentHTML('beforeend',deleteModal());bind();bindBackup();bindDaily();injectExpenseDaySelector();bindExpenseFilters();bindTripGuide();bindGuideShortcut();bindTripUtilities()}
function bind(){document.querySelectorAll<HTMLButtonElement>('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view as View;editingId=null;pendingDelete=null;document.body.dataset.adding='false';render();window.scrollTo(0,0)});document.querySelector('#openMenu')?.addEventListener('click',()=>{document.querySelector('.sidebar')?.classList.add('open');document.querySelector('.side-overlay')?.classList.add('show')});document.querySelector('.side-overlay')?.addEventListener('click',()=>{document.querySelector('.sidebar')?.classList.remove('open');document.querySelector('.side-overlay')?.classList.remove('show')});document.querySelectorAll('[data-add]').forEach(b=>b.addEventListener('click',()=>{editingId=null;document.body.dataset.adding='true';render()}));document.querySelectorAll<HTMLElement>('[data-edit]').forEach(b=>b.onclick=()=>{editingId=b.dataset.edit||null;document.body.dataset.adding='false';render()});document.querySelectorAll<HTMLElement>('[data-delete]').forEach(b=>b.onclick=()=>{pendingDelete=b.dataset.delete||null;render()});document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>{editingId=null;pendingDelete=null;document.body.dataset.adding='false';render()}));document.querySelector('#confirmDelete')?.addEventListener('click',()=>{data.expenses=data.expenses.filter(e=>e.id!==pendingDelete);pendingDelete=null;save();render();showToast('ลบรายการแล้ว')});const search=document.querySelector<HTMLInputElement>('#searchInput');if(search)search.oninput=()=>{query=search.value;render()};const filter=document.querySelector<HTMLSelectElement>('#categoryFilter');if(filter)filter.onchange=()=>{categoryFilter=filter.value;render()};document.querySelector<HTMLFormElement>('#expenseForm')?.addEventListener('submit',submitExpense);document.querySelector<HTMLFormElement>('#settingsForm')?.addEventListener('submit',submitSettings);document.querySelectorAll<HTMLInputElement>('.traveler-name').forEach(input=>input.onchange=()=>{const p=data.settings.travelers.find(x=>x.id===input.dataset.person);if(p&&input.value.trim()){p.name=input.value.trim();save();showToast('บันทึกชื่อแล้ว')}});document.querySelector('#resetData')?.addEventListener('click',()=>{if(confirm('คืนค่าข้อมูลทริปทั้งหมดเป็นค่าเริ่มต้น?')){data=clone(defaultData);save();render();showToast('คืนค่าเริ่มต้นแล้ว')}});document.querySelector<HTMLElement>('.modal [autofocus]')?.focus()}
function submitExpense(ev:Event){ev.preventDefault();const get=(id:string)=>document.querySelector<HTMLInputElement|HTMLSelectElement|HTMLTextAreaElement>(`#${id}`),amount=Number(get('expAmount')?.value),dayId=get('expDay')?.value||null,linkedDay=data.days.find(day=>day.id===dayId);if(!Number.isFinite(amount)||amount<0){showToast('กรุณาระบุจำนวนเงินที่ถูกต้อง','error');return}const next:Expense={id:editingId||crypto.randomUUID(),date:linkedDay?.date||get('expDate')?.value||'',dayId,item:get('expItem')?.value.trim()||'',category:get('expCategory')?.value as Category,amount,currency:get('expCurrency')?.value as Currency,payerId:get('expPayer')?.value||data.settings.travelers[0].id,status:get('expStatus')?.value as Status,note:get('expNote')?.value.trim()||''};if(!next.date||!next.item){showToast('กรุณากรอกวันที่และชื่อรายการ','error');return}if(editingId)data.expenses=data.expenses.map(e=>e.id===editingId?next:e);else data.expenses.unshift(next);editingId=null;document.body.dataset.adding='false';delete document.body.dataset.expenseDay;save();render();showToast('บันทึกรายการแล้ว')}
function submitSettings(ev:Event){ev.preventDefault();const tripName=document.querySelector<HTMLInputElement>('#tripName')?.value.trim(),budget=Number(document.querySelector<HTMLInputElement>('#budget')?.value),rate=Number(document.querySelector<HTMLInputElement>('#exchangeRate')?.value),start=document.querySelector<HTMLInputElement>('#startDate')?.value,end=document.querySelector<HTMLInputElement>('#endDate')?.value;if(!tripName||budget<0||rate<=0||!start||!end||start>end){showToast('กรุณาตรวจสอบข้อมูลการตั้งค่า','error');return}Object.assign(data.settings,{tripName,budgetTHB:budget,exchangeRate:rate,startDate:start,endDate:end});save();render();showToast('บันทึกการตั้งค่าแล้ว')}
function registerWebMCP(){if(!document.modelContext?.registerTool)return;document.modelContext.registerTool({name:'read_trip_summary',title:'อ่านสรุปทริปดานัง',description:'อ่านงบประมาณ ยอดจ่ายแล้ว ยอดคาดการณ์ และยอดคงเหลือ',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>totals()});document.modelContext.registerTool({name:'add_trip_expense',title:'เพิ่มค่าใช้จ่ายทริป',description:'เพิ่มค่าใช้จ่ายใหม่และอัปเดตยอดสรุปของทริปดานัง',inputSchema:{type:'object',properties:{date:{type:'string'},item:{type:'string'},category:{type:'string',enum:[...categories]},amount:{type:'number',minimum:0},currency:{type:'string',enum:['THB','VND']},payerId:{type:'string'},status:{type:'string',enum:['paid','planned']},note:{type:'string'}},required:['date','item','category','amount','currency','payerId','status'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:(input:Omit<Expense,'id'>)=>{if(!input.item?.trim()||input.amount<0||!data.settings.travelers.some(p=>p.id===input.payerId))throw new Error('ข้อมูลค่าใช้จ่ายไม่ถูกต้อง');const expense={...input,id:crypto.randomUUID(),note:input.note||''};data.expenses.unshift(expense);save();render();return{id:expense.id,totalTHB:totals().all}}})}
async function initialize(){render();const versionAtStart=localChangeVersion;try{const {loadOrCreateTrip,saveTrip,subscribeToTrip}=await getCloud();if(hasPendingSave){const pendingVersion=localChangeVersion;await saveTrip(clone(data));if(pendingVersion===localChangeVersion)setPendingSave(false)}else{const remoteData=await loadOrCreateTrip(data);if(!hasPendingSave&&localChangeVersion===versionAtStart){data=clone(remoteData);saveLocal()}}syncState=hasPendingSave?'saving':'synced';render();subscribeToTrip(next=>{if(hasPendingSave||JSON.stringify(next)===JSON.stringify(data))return;data=clone(next);saveLocal();render();showToast('อัปเดตข้อมูลจากอีกอุปกรณ์แล้ว')})}catch{syncState='offline';render();showToast('เชื่อมฐานข้อมูลไม่ได้ กำลังใช้ข้อมูลในเครื่อง','error')}}
registerCalculatorEvents(()=>{if(view==='calculator')render()});window.addEventListener('calculator-create-expense',(event)=>{const detail=(event as CustomEvent<{amount:number;currency:Currency}>).detail;editingId=null;document.body.dataset.adding='true';render();const amount=document.querySelector<HTMLInputElement>('#expAmount'),currency=document.querySelector<HTMLSelectElement>('#expCurrency');if(amount)amount.value=String(detail.amount);if(currency)currency.value=detail.currency});window.addEventListener('online',()=>{if(hasPendingSave)void flushSave()});registerWebMCP();void initialize()
